const text = row.oracle_text ?? '';
  if (ANY_NUMBER.test(text)) return Infinity;

  const capped = UP_TO_N.exec(text);
  if (capped) {
    // Group 1 is mandatory in UP_TO_N, so a match always populates it.
    const raw = capped[1]!.toLowerCase();
    // Try to parse as a plain integer first
    const intMatch = /^\d+$/.exec(raw);
    if (intMatch) {
      const n = Number(intMatch[0]);
      if (Number.isInteger(n) && n > 0) return n;
    }
    const limit = NUMBER_WORDS[raw];
    if (limit) return limit;
    // Unknown value: fall back to conservative default but warn the caller
    console.warn(`singletonLimit: cannot determine limit for "${text}"; using 1`);
  }

  return 1;

